window.kbPageData["views/entry/k-473c43235efd31f0"] = {"key":"entry/k-473c43235efd31f0","state":{"route":"entry/k-473c43235efd31f0"},"node":{"id":"k-473c43235efd31f0","mode":"k","title":"总体国家安全观与平安中国建设","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["总体国家安全观"],"qs":["政治理论必刷100题#64"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"主类":["制度与规则"],"出处性质":["专项题解析","理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"总体国家安全观是建设更高水平平安中国的重要遵循，各级党委和政府必须坚定不移贯彻，把发展和安全统一起来。","review":{"definition":"总体国家安全观是建设更高水平平安中国的重要遵循，各级党委和政府必须坚定不移贯彻，把发展和安全统一起来。","explanation":"2025年2月28日，习近平在中共中央政治局第十九次集体学习时要求各级党委和政府共同谋划、一体部署发展和安全。第②项把原表述中的“重要遵循”改成“唯一遵循”，因此错误。","references":[],"evidence":"总体国家安全观是建设更高水平平安中国的重要遵循","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"499077802f3e9111","label":"总体国家安全观","topic":"新时代中国特色社会主义思想","category":"非时政","text":"党的十八届三中全会《决定》提出：“设立国家安全委员会，完善国家安全体制和国家\n安全战略，确保国家安全。”\n2014 年 4 月 15 日，中央国家安全委员会召开第一次会议，习近平总书记创造性地提\n出总体国家安全观。\n党的十九大将“坚持总体国家安全观”纳入新时代坚持和发展中国特色社会主义的基本\n方略并写入党章。\n2020 年 12 月 11 日，十九届中央政治局举行第二十六次集体学习，习近平总书记就\n贯彻总体国家安全观提出“十个坚持”的重要要求，标志着总体国家安全观理论体系的正式\n确立。\n“十个坚持”是指：\n（1）坚持党对国家安全工作的绝对领导，\n（2）坚持中国特色国家\n安全道路，（3）坚持以人民安全为宗旨，（4）坚持统筹发展和安全，（5）坚持把政治安全\n放在首要位置，（6）坚持统筹推进各领域安全，（7）坚持把防范化解国家安全风险摆在突\n出位置，\n（8）坚持推进国际共同安全，\n（9）坚持推进国家安全体系和能力现代化，\n（10）坚\n持加强国家安全干部队伍建设。\n党的二十大对国家安全工作进行专章部署，提出：“坚持以人民安全为宗旨、以政治安\n全为根本、以经济安全为基础、以军事科技文化社会安全为保障、以促进国际安全为依托，\n统筹外部安全和内部安全、国土安全和国民安全、传统安全和非传统安全、自身安全和共同\n安全，统筹维护和塑造国家安全，夯实国家安全和社会稳定基层基础，完善参与全球安全治\n理机制，建设更高水平的平安中国，以新安全格局保障新发展格局。”\n（粉笔敲黑板：注意总\n体国家安全关 5 个安全的地位，尤其是政治安全为根本）\n总体国家安全观的关键是“总体”。强调大安全理念，涵盖政治、军事、国土、经济、\n金融、文化、社会、科技、网络、粮食、生态、资源、核、海外利益、太空、深海、极地、\n生物、人工智能、数据等诸多领域，而且将随着社会发展不断动态调整。总体国家安全观的\n核心要义，集中体现为“十个坚持”。\n“一个总体”、\n“十个坚持”有机融合、有机统一，凝结\n着我们党坚持和发展中国特色国家安全的宝贵经验，反映了以习近平同志为核心的党中央对\n国家安全工作规律性认识的深化、拓展、升华。","source":{"doc":"3ccc56f4000d1642c2d1","first":28,"last":29,"page":28,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{"政治理论必刷100题#64":{"paper":"政治理论必刷100题","n":64,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",19],"asrc":["国省考政治理论必刷100题.pdf",72],"card":"89787f8ea9e995e9c59690fc","links":[{"id":"k-473c43235efd31f0","role":"直接考查","why":"政策原文将总体国家安全观定位为平安中国建设的重要遵循。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-473c43235efd31f0":[["政治理论必刷100题#64"]]}};
